package com.blackice.bc1.editor;
import org.junit.Test;
import static org.junit.Assert.*;
public class FillStyleTest {
 @Test public void quickInsertionCentersAndClampsWithoutTruncation(){assertEquals(3500,QuickInsertion.start(5000,3000));assertEquals(0,QuickInsertion.start(20,3000));assertEquals(500,QuickInsertion.start(1500,2000));}
 @Test public void fillRoundTripAndCopyPreserveIndependentTracks()throws Exception{EditProject p=new EditProject();EditProject.Overlay o=ShapeCatalog.create(26,0);o.fill=new FillStyle(0x80FF0000);o.fill.gradient=true;String id=o.fill.active.get(0);FillStyle.Stop stop=o.fill.stops.get(id);stop.color.toggle(0);stop.color.set(2000,0x400000FF);stop.position.toggle(0);stop.position.set(2000,.4);o.fill.angle.toggle(0);o.fill.angle.set(2000,180);p.overlays.add(o);EditProject.Overlay loaded=ProjectStore.decode(ProjectStore.encode(p)).overlays.get(0);assertEquals(id,loaded.fill.active.get(0));assertEquals(.2,loaded.fill.stops.get(id).position.at(1000),1e-6);assertEquals(90,loaded.fill.angle.at(1000),0);assertEquals(0x60800080,(int)loaded.fill.stops.get(id).color.at(1000));FillStyle copy=loaded.fill.copy();copy.stops.get(id).position.set(2000,.8);assertEquals(.4,loaded.fill.stops.get(id).position.at(2000),0);}
 @Test public void editingUnanimatedPropertyDoesNotCreateKeys(){FillStyle f=new FillStyle(-1);f.solid.toggle(0);f.solid.set(1000,0xFF000000);f.angle.set(500,90);assertTrue(f.angle.keys.isEmpty());assertEquals(90,f.angle.base,0);assertEquals(2,f.solid.keys.size());}
 @Test public void stopMembershipHoldsAndNeverPairsUnrelatedIds(){FillStyle f=new FillStyle(-1);f.angle.toggle(0);String original=f.active.get(0);String added=f.add(1000,.5,0xFFFF0000);assertEquals(2,f.ids(999).size());assertEquals(3,f.ids(1000).size());assertTrue(f.ids(1000).contains(added));f.remove(2000,original);assertTrue(f.ids(1999).contains(original));assertFalse(f.ids(2000).contains(original));assertEquals(2,f.ids(2000).size());f.validate();}
 @Test public void splitPreservesVisibleRampAndLocalKeys(){FillStyle f=new FillStyle(0xFF000000);f.solid.toggle(0);f.solid.set(2000,0xFFFFFFFF);f.angle.toggle(0);f.angle.set(2000,180);String id=f.add(500,.3,0xFF00FF00);FillStyle before=f.copy();f.split(1000);assertEquals(before.solid.at(1000),f.solid.at(0),0);assertEquals(before.angle.at(1500),f.angle.at(500),1e-6);assertEquals(before.ids(1000),f.ids(0));assertTrue(f.ids(0).contains(id));}
 @Test public void keyNavigationDoesNotMutateState()throws Exception{FillStyle f=new FillStyle(-1);f.solid.toggle(100);f.angle.toggle(900);String before=f.json().toString();assertEquals(900,f.neighbor(500,true,10));assertEquals(100,f.neighbor(500,false,10));assertEquals(before,f.json().toString());}
 @Test public void removingLastKeyRetainsDisplayedValue(){FillStyle.Track t=new FillStyle.Track(0xFF112233,true);t.toggle(0);t.set(0,0x80445566);t.toggle(0);assertTrue(t.keys.isEmpty());assertEquals(0x80445566,(int)t.at(0));}
 @Test public void largeShapeScaleAndKeysSurviveStorage()throws Exception{EditProject p=new EditProject();EditProject.Overlay o=ShapeCatalog.create(2,0);o.scale=70;o.heightScale=70;o.motion.put(Motion.SCALE,new Motion.Key(0,70));o.motion.put(Motion.SCALE,new Motion.Key(2000,100));o.motion.put(Motion.HEIGHT,new Motion.Key(0,70));o.motion.put(Motion.HEIGHT,new Motion.Key(2000,100));p.overlays.add(o);EditProject.Overlay saved=ProjectStore.decode(ProjectStore.encode(p)).overlays.get(0);assertEquals(100,TransformMath.of(saved,2000).scale,0);assertTrue(Motion.allowed(Motion.SCALE,100));assertFalse(Motion.allowed(Motion.SCALE,Float.POSITIVE_INFINITY));assertFalse(Motion.allowed(Motion.HEIGHT,Float.NaN));}
 @Test public void legacyColorLoadsWithoutCreatingFillAnimation()throws Exception{EditProject p=new EditProject();EditProject.Overlay o=ShapeCatalog.create(1,0);o.color=0x80224466;p.overlays.add(o);org.json.JSONObject j=new org.json.JSONObject(ProjectStore.encode(p));j.put("schema",9);j.getJSONArray("overlays").getJSONObject(0).remove("fill");EditProject.Overlay loaded=ProjectStore.decode(j.toString()).overlays.get(0);assertNull(loaded.fill);assertEquals(o.color,loaded.color);}
 @Test public void rejectNonFiniteAndOutOfBoundsFill(){FillStyle f=new FillStyle(-1);try{f.angle.set(0,Double.NaN);fail();}catch(IllegalArgumentException expected){}f.stops.get(f.active.get(0)).position.base=2;try{f.validate();fail();}catch(IllegalArgumentException expected){}}
 @Test public void keepTwoStopsAndSeparateModes(){FillStyle f=new FillStyle(0x55FF0000);try{f.remove(0,f.active.get(0));fail();}catch(IllegalArgumentException expected){}f.gradient=true;f.stops.get(f.active.get(0)).color.set(0,0xFF00FF00);f.gradient=false;assertEquals(0x55FF0000,(int)f.solid.at(0));assertEquals(0xFF00FF00,(int)f.stops.get(f.active.get(0)).color.at(0));}
}
